    /*
     * Add to the Encounters
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	CarePlan
     */
    public CarePlan addToEncounters( UUID parentId, Encounter addTo ) {
	    LOGGER.info("handling AssignEncountersToCarePlanEvent - " );
	    
	    CarePlan parentEntity = repository.findById(parentId).get();
	    Encounter child = registry.project( Encounter.class, addTo.getEncounterId());
	    
	    parentEntity.getEncounters().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

